import React, { useState } from "react";
import _ from "lodash";
import Pagination from "../../shared/hoc/pagination/pagination";
import ProductCard from "../../shared/product-card/product-card";
import Accordeon from "../../shared/hoc/accordeon/accordeon";
import Loader from "../../shared/loader/loader";
import usePagination from "../../hooks/usePagination";
import { useTypedSelector } from "../../types";
import {} from "../../store/actions/productAction";
import { IProduct } from "../../types/store/productStoreType";
import { useTranslation } from "react-i18next";
import { IPurchase } from "../../types/store/orderStoreType";
import { ICategory } from "../../types/store/categoryStoreType";
import Button from "../../shared/button/button";

export interface IOrderCategory {
  order: IPurchase;
}

const ProductsList = () => {
  const { t } = useTranslation();
  const [searchValue, setSearchValue] = useState("");
  const [selectedCategory, setSelectedCategory] = useState();
  const [sortBy, setSortBy] = useState<{ order: any }>({
    order: "asc",
  });

  const productsState = useTypedSelector((state) => state.products.products);
  const categories = useTypedSelector((state) => state.category.categories);

  const productsLoading = useTypedSelector(
    (state) => state.products.productsRequest
  );
  const categoryLoading = useTypedSelector(
    (state) => state.category.categoriesRequest
  );
  const productsError = useTypedSelector(
    (state) => state.products.productsErrorMessage
  );
  const categoryError = useTypedSelector(
    (state) => state.category.categoriesErrorMessage
  );

  const handleSearch = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchValue(event.target.value);
  };

  const handleCategorySelect = (category: any) => {
    setSelectedCategory(category);
  };

  function searchProducts(products: IProduct[]) {
    if (products) {
      if (selectedCategory) {
        const newData: IProduct[] = [];
        products.forEach((product: IProduct) => {
          const productCategories = product.categories.map(
            (category: ICategory) => String(category.id)
          );
          if (productCategories.includes(selectedCategory)) {
            newData.push(product);
          }
        });
        return newData.filter((product) =>
          product.name.toLowerCase().includes(searchValue.toLowerCase())
        );
      }

      return products.filter((product: IProduct) =>
        product.name.toLowerCase().includes(searchValue.toLowerCase())
      );
    }
    return [];
  }

  const productsList = searchProducts(productsState);

  const sortedProducts = sortBy?.order
    ? _.orderBy(productsList, "price", [sortBy.order])
    : productsList;

  const { currentPage, showCurrentEntity, jump, maxPage, next, prev } =
    usePagination(sortedProducts, 6);

  const products = showCurrentEntity();

  const handleSort = () => {
    const updated = {
      ...sortBy,
      order: sortBy?.order === "asc" ? "desc" : "asc",
    };
    setSortBy(updated);
  };

  const handleSkipSort = () => {
    setSortBy({ order: "asc" });
  };

  if (productsLoading || categoryLoading) {
    return (
      <section className="product section container" id="products">
        <Loader />
      </section>
    );
  }

  if (productsError || categoryError) {
    return (
      <section className="product section container">
        <h3>{productsError || categoryError}</h3>
      </section>
    );
  }

  return (
    <section className="product section container">
      <h2 className="section__title-center">{t("Our products")} </h2>
      <div className="search__container">
        <div className="footer__subscribe search__input">
          <input
            type="text"
            placeholder={`${t("Enter plant name")}...`}
            className="footer__input"
            value={searchValue}
            onChange={handleSearch}
          />
        </div>
        {sortBy?.order === "desc" ? (
          <Button
            buttonStyle="arrow-down"
            buttonType="button"
            buttonHandler={() => handleSort()}
          />
        ) : (
          <Button
            buttonStyle="arrow-up"
            buttonType="button"
            buttonHandler={() => handleSort()}
          />
        )}
        {sortBy?.order ? (
          <Button
            buttonStyle="close"
            buttonType="button"
            buttonHandler={() => handleSkipSort()}
          />
        ) : null}
      </div>
      <div className="accordeon__container">
        <Accordeon
          title={t("Categories")}
          categories={categories}
          onCategorySelected={handleCategorySelect}
        />
      </div>
      {products.length ? (
        <>
          <div className="product__container grid">
            {products.map((product: IProduct) => (
              <ProductCard
                categories={categories}
                product={product}
                key={product.id}
              />
            ))}
          </div>
          <Pagination
            currentPage={currentPage}
            jump={jump}
            maxPage={maxPage}
            next={next}
            prev={prev}
          />
        </>
      ) : (
        <h3 className="container-center">{t("There are no products")}</h3>
      )}
    </section>
  );
};

export default ProductsList;
