import { FC, useMemo } from "react";
import { useTypedDispatch, useTypedSelector } from "../../types";
import {
  IProduct,
  IProductWithCategories,
} from "../../types/store/productStoreType";
import { toast } from "react-toastify";
import { addProductToCart } from "../../store/actions/cartAction";
import { dislikeProduct, likeProduct } from "../../store/actions/productAction";
import { ICategory } from "../../types/store/categoryStoreType";
import { NotFound } from "../../shared/not-found/not-found";
import { useTranslation } from "react-i18next";
import StarRatings from "react-star-ratings";
import { rateProduct } from "../../store/actions/reviewAction";
import { IReview } from "../../types/store/reviewStoreType";
import { ReviewFeed } from "../../components/review-feed/review-feed";
import MyReview from "../../components/my-review/my-review";
import { ICartItem } from "../../types/store/cartStoreType";
import BlurCircles from "../../components/blur-circles/blur-circles";

interface IProductProps {
  productId: string;
}

const Product: FC<IProductProps> = ({ productId }) => {
  const { t } = useTranslation();
  const dispatch = useTypedDispatch();
  const products = useTypedSelector((state) => state.products.products);
  const user = useTypedSelector((state) => state.user.userData);
  const cart = useTypedSelector((state) => state.cart.cart);
  const reviews = useTypedSelector((state) => state.review.review) || [];
  const currentReviews = reviews?.filter((i) => i.product?.id === +productId);
  const myReviewOnProduct = reviews?.filter(
    (i) => i.product?.id === +productId && i.user?.email === user.email
  );

  const userLikedProducts: number[] =
    user.favourite?.map((i: IProduct) => i.id) || [];

  const getProductById = (
    productId: string,
    products: IProductWithCategories[]
  ) => products.find((p: IProductWithCategories) => p.id === Number(productId));

  const currentProduct = getProductById(productId, products);

  const handleAdd = (product: IProduct) => {
    if (user.email) {
      dispatch(addProductToCart(product));
    } else {
      toast.info(t("Sign in to add to cart"));
    }
  };

  const handleLike = (id: number) => {
    const likedProductsIds = user.favourite?.map((i: IProduct) => i.id);

    if (user.email && !likedProductsIds.includes(id)) {
      dispatch(likeProduct(id));
    } else if (user.email && likedProductsIds.includes(id)) {
      dispatch(dislikeProduct(id));
    } else {
      toast.info(t("Sign in to add product to favorites"));
    }
  };

  const handleRate = (id: number, rate: number) => {
    dispatch(rateProduct({ productId: id, rate }));
  };

  const countProducts = useMemo(() => {
    if (!cart?.cartItem?.length) return 0;
    const counter = cart?.cartItem?.find(
      (item: ICartItem) => item.product.id === +productId
    )?.quantity;
    return typeof counter === "number" ? counter : 0;
  }, [productId, cart?.cartItem]);

  const countAverageRate = useMemo(() => {
    if (!currentReviews?.length) return 0;
    const counter =
      currentReviews?.reduce(
        (acc, item: IReview) => (acc += item.rate ? item.rate : 0),
        0
      ) / currentReviews?.length;
    return typeof counter === "number" ? counter : 0;
  }, [currentReviews?.length, handleRate]);

  const circles = [
    { size: 65, color: "rgba(255, 0, 0, 0.7)", blur: 100 },
    { size: 65, color: "rgba(0, 255, 0, 0.7)", blur: 100 },
    { size: 65, color: "rgba(255, 252, 49, 0.7)", blur: 100 },
  ];

  return currentProduct ? (
    <section className="container section">
      <h2 className="section__title-center">{currentProduct?.name}</h2>
      <div className="product-solo__container">
        <div className="container-center">
          <BlurCircles circles={circles} width={300} height={250} />
          <img
            src={currentProduct?.image}
            alt={currentProduct?.name}
            className="product-solo__img"
          />

          <div>
            {currentProduct?.categories?.map((category: ICategory) => (
              <span className="product__category" key={category.id}>
                {category.name}
              </span>
            ))}
          </div>
          <div className="product-solo__rating">
            <StarRatings
              rating={countAverageRate}
              starRatedColor="orange"
              changeRating={(rate) => handleRate(+productId, rate)}
              starDimension="30px"
              numberOfStars={5}
              name="rating"
            />
            <p className="product-solo__rating-counter">
              ({currentReviews?.length})
            </p>
          </div>
        </div>
        <p className="product-solo__description">
          {currentProduct?.description}
        </p>
      </div>
      <div className="container-center">
        <span className="product__price">${currentProduct?.price}</span>
        <button
          className={`button--flex product-solo__like-button ${
            userLikedProducts?.includes(+productId)
              ? "product-solo__like-button-active"
              : null
          }`}
          type="button"
          onClick={() => handleLike(+productId)}
        >
          <i className="ri-heart-add-fill" />
        </button>
        <button
          onClick={() => handleAdd(currentProduct)}
          className="button--flex product-solo__button"
          type="button"
        >
          <i className="ri-shopping-bag-line" />
          {countProducts !== 0 ? (
            <div className="product-solo__cart-counter" role="status">
              {countProducts}
            </div>
          ) : null}
        </button>
      </div>
      <hr />
      {myReviewOnProduct?.length ? (
        <MyReview review={myReviewOnProduct} />
      ) : null}
      <ReviewFeed reviews={currentReviews} />
      <hr />
    </section>
  ) : (
    <NotFound />
  );
};

export default Product;
