import { Action } from "redux";
import { useDispatch, TypedUseSelectorHook, useSelector } from "react-redux";
import { ThunkAction, ThunkDispatch } from "redux-thunk";
import { rootReducer } from "../store";
import { IUserData } from "./store/userStoreType";
export const EXCEL_TYPE =
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

export type RootState = ReturnType<typeof rootReducer>;

export const useTypedDispatch = () => useDispatch<AppThunkDispatch>();
export const useTypedSelector: TypedUseSelectorHook<RootState> = useSelector;

export type AppThunk<ReturnType = void> = ThunkAction<
  ReturnType,
  RootState,
  unknown,
  Action<string>
>;
export type AppThunkDispatch = ThunkDispatch<RootState, never, Action<string>>;

export interface GenericObject {
  [key: string]: any;
}

export interface IUseLocation {
  from: {
    pathname: string;
  };
  state: {
    background: string;
    [prop: string]: string;
  };
  [key: string]: any;
}

export interface IUseParams {
  id: string;
}

export type TUser = {
  email: string;
  name: string;
  password?: string;
  token?: string;
};

export type TUserFetchResponse = {
  success: boolean;
  user: IUserData;
};

export type TSetCookieProps = {
  [key: string]: any | {};
};

export type TUserError = {
  [key: string]: any | {};
};

export type TEventTarget = {
  value: string;
  name: string;
};

export type TError = {
  success?: boolean;
  message?: string;
  status?: number;
};

export type TRefreshData = {
  success: boolean;
  accessToken: string;
};

export type TResponseWithoutPayload = {
  success: boolean;
  message: string;
};

export interface ISuccessResponse {
  success: boolean;
}
