import { deleteCookie, getCookie, setCookie } from "../utils/cookie";
import { config } from "../utils/api";
import {
  GetCodeDto,
  LoginGoogleDto,
  LoginYandexDto,
  LogoutDto,
  ResetPasswordDto,
  SendCodeDto,
  SigninDto,
  SignupDto,
} from "../types/store/userStoreType";

const authEndPoint = "auth";

const authService = {
  checkResponse: async (res: any) => {
    if (res.ok) {
      return res.json();
    }
    const errorData = await res.json();
    return Promise.reject(errorData);
  },

  userRequest: async () => {
    const url = `${config.apiEndPoint}/${authEndPoint}/me`;
    const options = {
      method: "GET",
      headers: {
        Authorization: "Bearer " + getCookie("accessToken"),
        "Content-Type": "application/json",
      },
    };

    return fetch(url, options)
      .then((res) => {
        return authService.checkResponse(res);
      })
      .catch(async (error: any) => {
        if (error.error.message.message === "Access token has expired") {
          const refreshData: any = await authService.refreshTokenRequest();
          setCookie("accessToken", refreshData.updatedAccessToken, {});
          options.headers.Authorization = "Bearer " + getCookie("accessToken");
          const res = await fetch(url, options);
          return await authService.checkResponse(res);
        } else {
          return Promise.reject(error);
        }
      });
  },

  refreshTokenRequest: async () => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/refresh`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
        Authorization: "Bearer " + getCookie("accessToken"),
      },
      body: JSON.stringify({
        refreshToken: getCookie("refreshToken"),
      }),
    })
      .then(authService.checkResponse)
      .catch((error) => {
        if (error.error.message.message === "Refresh token expired") {
          deleteCookie("refreshToken");
          deleteCookie("accessToken");
        }
        throw new Error("Access denied");
      });
  },

  registerRequest: ({
    firstName,
    lastName,
    mobileNumber,
    email,
    password,
  }: SignupDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/signup`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        firstName,
        lastName,
        mobileNumber,
        email,
        password,
      }),
    });
  },

  loginRequest: async ({ email, password }: SigninDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/signin`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        email: email,
        password: password,
      }),
    });
  },

  logoutRequest: async ({ email }: LogoutDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/logout`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        email: email,
      }),
    });
  },

  getCodeRequest: async ({ email }: GetCodeDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/get-code`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        email: email,
      }),
    });
  },

  sendCodeRequest: async ({ code, email }: SendCodeDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/send-code`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        code,
        email,
      }),
    });
  },

  resetPasswordRequest: async ({ newPassword, email }: ResetPasswordDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/reset-password`, {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        newPassword,
        email,
      }),
    });
  },

  loginYandexRequest: async ({ code }: LoginYandexDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/login-yandex`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        code,
      }),
    });
  },

  loginGoogleRequest: async ({ access_token }: LoginGoogleDto) => {
    return fetch(`${config.apiEndPoint}/${authEndPoint}/login-google`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json;charset=utf-8",
      },
      body: JSON.stringify({
        access_token,
      }),
    });
  },
};

export default authService;
